import React, { Component } from "react";
import { Modal } from "antd";
import { withRouter } from "react-router-dom"; // To use history.push()

class Footer extends Component {
  state = {
    isModalVisible: false, // Controls modal visibility
  };

  handleNext = (e) => {
    this.props.handleFooterButtons(e.currentTarget.classList[0]);
  };

  // Show modal only for flagging a question
  showFlagModal = () => {
    this.setState({ isModalVisible: true });
  };

  // Handle "OK" action in modal (confirm flagging)
  handleOk = () => {
    this.setState({ isModalVisible: false });
    // Perform the action when the question is flagged (e.g., mark as flagged)
    this.props.handleFlagQuestion(); // Custom function for flagging
  };

  // Handle "Cancel" action in modal
  handleCancel = () => {
    this.setState({ isModalVisible: false });
  };

  render() {
    return (
      <>
        <div className="footer__wrapper">
          <div className="left__footer">
            <div
              className="previous__question box"
              onClick={(e) => this.handleNext(e)}
            >
              Previous
            </div>
            <div
              className="flag__question box"
              onClick={this.showFlagModal} // Trigger the modal on flag click
            >
              Flag
            </div>
            <div
              className="next__question box"
              onClick={(e) => this.handleNext(e)}
            >
              Next
            </div>
          </div>
          <div className="right__footer">
            <div className="end__test box" onClick={this.props.handleSubmitTest}>
              End Test
            </div>
          </div>
        </div>

        {/* Modal for confirming flagging a question */}
        <Modal
          title="Confirm Flag"
          visible={this.state.isModalVisible}
          onOk={this.handleOk}
          onCancel={this.handleCancel}
          okText="Flag"
          cancelText="Cancel"
        >
          <p>Are you sure you want to flag this question for review?</p>
        </Modal>
      </>
    );
  }
}

export default withRouter(Footer);
